<?php declare(strict_types=1); require dirname(__DIR__,2).'/includes/bootstrap.php'; require_permission('users.view');$id=filter_var(input('id'),FILTER_VALIDATE_INT);if(!$id){http_response_code(404);exit('Not found');}
if(is_post()){require_permission('users.block');verify_csrf();$target=strtoupper((string)input('status'));$reason=trim((string)input('reason'));if(!in_array($target,['ACTIVE','BLOCKED','SUSPENDED'],true)||($target!=='ACTIVE'&&$reason===''))flash('error','A valid status and reason are required.');else{$pdo=db();$pdo->beginTransaction();try{$old=$pdo->prepare('SELECT status,status_reason FROM users WHERE id=? FOR UPDATE');$old->execute([$id]);$before=$old->fetch();if(!$before)throw new RuntimeException('User not found.');$pdo->prepare('UPDATE users SET status=?,status_reason=?,updated_at=NOW() WHERE id=?')->execute([$target,$target==='ACTIVE'?null:$reason,$id]);if($target!=='ACTIVE')$pdo->prepare('UPDATE user_sessions SET revoked_at=NOW() WHERE user_id=? AND revoked_at IS NULL')->execute([$id]);audit_log((int)admin()['id'],'USER_STATUS_CHANGED','users',(string)$id,$before,['status'=>$target,'reason'=>$reason]);log_security((int)$id,'USER_'.$target,$target==='ACTIVE'?'LOW':'HIGH','Administrator changed user status',['reason'=>$reason]);$pdo->commit();flash('success','User status updated.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e instanceof PDOException?'Could not update user status.':$e->getMessage());}}redirect('/admin/users/view.php?id='.$id);}
$stmt=db()->prepare('SELECT u.*,w.id wallet_id,w.balance,w.currency,w.status wallet_status FROM users u LEFT JOIN wallets w ON w.user_id=u.id WHERE u.id=?');$stmt->execute([$id]);$user=$stmt->fetch();if(!$user){http_response_code(404);exit('Not found');}
$tx=db()->prepare('SELECT * FROM wallet_transactions WHERE user_id=? ORDER BY id DESC LIMIT 10');$tx->execute([$id]);$transactions=$tx->fetchAll();$dev=db()->prepare('SELECT * FROM user_devices WHERE user_id=? ORDER BY id DESC');$dev->execute([$id]);$devices=$dev->fetchAll();$pageTitle='User #'.$id;$pageSubtitle=$user['name'];require APP_ROOT.'/includes/header.php';?>
<div class="grid detail-grid"><section class="panel"><div class="panel-head"><h2>Account information</h2><span class="badge <?=strtolower(e($user['status']))?>"><?=e($user['status'])?></span></div><div class="kv"><span>Name</span><strong><?=e($user['name'])?></strong></div><div class="kv"><span>Email</span><strong><?=e($user['email']??'—')?></strong></div><div class="kv"><span>Mobile</span><strong><?=e($user['mobile'])?></strong></div><div class="kv"><span>Last login</span><strong><?=e($user['last_login_at']??'Never')?> · <?=e($user['last_login_ip']??'—')?></strong></div><div class="kv"><span>Risk level</span><strong class="risk <?=strtolower(e($user['risk_level']))?>"><?=e($user['risk_level'])?></strong></div></section><section class="panel"><div class="panel-head"><h2>Wallet</h2><?php if(can('wallet.credit')):?><a class="btn small" href="<?=e(app_url('/admin/wallets/adjust.php?user_id='.$id))?>">Adjust balance</a><?php endif?></div><span class="label">Available balance</span><span class="value"><?=money($user['balance']??0)?></span><div class="kv"><span>Currency</span><strong><?=e($user['currency']??'INR')?></strong></div><div class="kv"><span>Wallet status</span><strong><?=e($user['wallet_status']??'Not created')?></strong></div></section></div>
<?php if(can('users.block')):?><section class="panel"><div class="panel-head"><h2>Change account status</h2></div><form method="post" class="form-grid" data-confirm="This will change the user's access immediately. Continue?"><?=csrf_field()?><div class="field"><label>Status</label><select name="status" required><?php foreach(['ACTIVE','BLOCKED','SUSPENDED'] as $s):?><option <?=$user['status']===$s?'selected':''?>><?=$s?></option><?php endforeach?></select></div><div class="field"><label>Reason (required for block/suspend)</label><input name="reason" maxlength="500"></div><div class="field full"><button class="btn danger">Update status</button></div></form></section><?php endif?>
<section class="panel"><div class="panel-head"><h2>Recent transactions</h2></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Type</th><th>Amount</th><th>Previous</th><th>New</th><th>Date</th></tr></thead><tbody><?php foreach($transactions as $t):?><tr><td><?=e($t['transaction_id'])?></td><td><?=e($t['type'])?></td><td><?=money($t['amount'])?></td><td><?=money($t['previous_balance'])?></td><td><?=money($t['new_balance'])?></td><td><?=e($t['created_at'])?></td></tr><?php endforeach?></tbody></table></div></section>
<section class="panel"><div class="panel-head"><h2>Registered devices</h2></div><div class="table-wrap"><table><thead><tr><th>Device</th><th>Platform</th><th>IP</th><th>Status</th><th>Last active</th></tr></thead><tbody><?php foreach($devices as $d):?><tr><td><?=e($d['device_name']??$d['device_id'])?></td><td><?=e(($d['platform']??'—').' '.($d['os_version']??''))?></td><td><?=e($d['ip_address']??'—')?></td><td><span class="badge <?=strtolower(e($d['status']))?>"><?=e($d['status'])?></span></td><td><?=e($d['last_active_at']??'—')?></td></tr><?php endforeach?></tbody></table></div></section><?php require APP_ROOT.'/includes/footer.php';
